def semver_sort(versions):
    def parse_key(v):
        # strip build metadata
        main_and_pre = v.split('+', 1)[0]
        if '-' in main_and_pre:
            main_part, pre_part = main_and_pre.split('-', 1)
            has_pre = True
        else:
            main_part = main_and_pre
            pre_part = ''
            has_pre = False

        nums = main_part.split('.')
        major, minor, patch = (int(nums[0]), int(nums[1]), int(nums[2]))

        presence_order = 0 if has_pre else 1

        if has_pre:
            idents = pre_part.split('.')
            ident_keys = []
            for ident in idents:
                if ident.isdigit():
                    ident_keys.append((0, int(ident)))
                else:
                    ident_keys.append((1, ident))
            ident_keys = tuple(ident_keys)
        else:
            ident_keys = tuple()

        return (major, minor, patch, presence_order, ident_keys)

    return sorted(versions, key=parse_key)

